// Utility: clamp
const clamp = (n, min, max) => Math.max(min, Math.min(max, n));

// Convert lon/lat → pixel on an equirectangular map of size (w,h)
function lonLatToXY(lon, lat, w, h) {
  const x = ((lon + 180) / 360) * w;
  const y = ((90 - lat) / 180) * h;
  return { x, y };
}

// World map cropper: shows a viewport centered on the job's location with smooth panning
function MapCrop({ src, lat, lon, location, viewW = 289, viewH = 100 }) {
  const imgRef = useRef(null);
  const [dims, setDims] = useState({ w: 0, h: 0 });

  useEffect(() => {
    const img = imgRef.current;
    if (!img) return;

    const onLoad = () => {
      const w = img.naturalWidth || img.width || 0;
      const h = img.naturalHeight || img.height || 0;
      setDims({ w, h });
    };

    if (img.complete) onLoad();
    else img.addEventListener("load", onLoad, { once: true });

    return () => img && img.removeEventListener("load", onLoad);
  }, []);

  let style;
  if (dims.w && dims.h && typeof lat === "number" && typeof lon === "number") {
    const { x, y } = lonLatToXY(lon, lat, dims.w, dims.h);
    const left = clamp(x - viewW / 2, 0, Math.max(0, dims.w - viewW));
    const top = clamp(y - viewH / 2, 0, Math.max(0, dims.h - viewH));
    style = {
      width: `${dims.w}px`,
      height: `${dims.h}px`,
      transform: `translate(${-left}px, ${-top}px)`,
    };
  }

  return (
    <div className="relative w-[289px] h-[100px] overflow-hidden rounded-xl border border-white/10 bg-white/[0.03]">
      <img
        ref={imgRef}
        src={src}
        alt="world map"
        className="select-none pointer-events-none absolute top-0 left-0 transition-transform duration-700 ease-out max-w-none"
        style={style}
      />
      {location && (
        <div className="pointer-events-none absolute bottom-3 left-1/2 flex -translate-x-1/2 items-center gap-2 text-white drop-shadow-[0_6px_12px_rgba(6,9,16,0.55)]">
          <img
            src={LOCATION_ICON_SRC}
            alt=""
            className="h-[18px] w-[18px] object-contain xl:h-[22px] xl:w-[22px]"
          />
          <span className="text-xs font-semibold tracking-wide whitespace-nowrap xl:text-sm">
            {location}
          </span>
        </div>
      )}
    </div>
  );
}

